import * as Tone from "tone";
import { useState, useRef, useEffect, useCallback, useMemo } from "react";

const PHI = 1.6180339887;
const IMG_TARGET_MS = 120000; // image transcription is exactly 2:00 regardless of grid
const CWIN = 55;
const KB_WIN = 65;
const DN = 25, DB = 16, DH = 26;
const GOLD = '#c9a84c';
const S_BASE = "https://cdn.jsdelivr.net/gh/Tonejs/audio@master/salamander/";
const S_URLS = {"A0":"A0.mp3","C1":"C1.mp3","D#1":"Ds1.mp3","F#1":"Fs1.mp3","A1":"A1.mp3","C2":"C2.mp3","D#2":"Ds2.mp3","F#2":"Fs2.mp3","A2":"A2.mp3","C3":"C3.mp3","D#3":"Ds3.mp3","F#3":"Fs3.mp3","A3":"A3.mp3","C4":"C4.mp3","D#4":"Ds4.mp3","F#4":"Fs4.mp3","A4":"A4.mp3","C5":"C5.mp3","D#5":"Ds5.mp3","F#5":"Fs5.mp3","A5":"A5.mp3","C6":"C6.mp3","D#6":"Ds6.mp3","F#6":"Fs6.mp3","A6":"A6.mp3","C7":"C7.mp3","D#7":"Ds7.mp3","F#7":"Fs7.mp3","A7":"A7.mp3","C8":"C8.mp3"};

const m2f = m => 440 * Math.pow(2, (m - 69) / 12);
const wlToRgb = wl => {
  let r=0,g=0,b=0;
  if(wl>=380&&wl<440){r=(440-wl)/60;b=1}else if(wl>=440&&wl<490){g=(wl-440)/50;b=1}
  else if(wl>=490&&wl<510){g=1;b=(510-wl)/20}else if(wl>=510&&wl<580){r=(wl-510)/70;g=1}
  else if(wl>=580&&wl<645){r=1;g=(645-wl)/65}else if(wl>=645&&wl<=780){r=1}
  const f=wl<380||wl>780?0:wl<420?0.3+0.7*(wl-380)/40:wl<=700?1:Math.max(0,0.3+0.7*(780-wl)/80);
  return [Math.round(255*Math.pow(Math.max(0,r*f),.8)),Math.round(255*Math.pow(Math.max(0,g*f),.8)),Math.round(255*Math.pow(Math.max(0,b*f),.8))];
};
const octL = m => 12 + Math.max(0,Math.min(8,Math.floor(m/12)-1))/8*76;
const toHsl = (r,g,b) => {
  r/=255;g/=255;b/=255;
  const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn,l=(mx+mn)/2;
  if(!d)return[0,0,l*100];
  const s=d/(1-Math.abs(2*l-1));
  let h=mx===r?(g-b)/d:mx===g?(b-r)/d+2:(r-g)/d+4;
  return[(((h%6)+6)%6)/6*360,s*100,l*100];
};
const COF=[0,210,60,270,120,330,180,30,240,90,300,150];
const fromHsl=(h,s,l)=>{s/=100;l/=100;const k=n=>(n+h/30)%12,a=s*Math.min(l,1-l),f=n=>Math.round((l-a*Math.max(-1,Math.min(k(n)-3,Math.min(9-k(n),1))))*255);return[f(0),f(8),f(4)];};
const harmCol=(m,v=100)=>{const[r,g,b]=fromHsl(COF[m%12],75+(v/127)*15,octL(m));return[r,g,b,0.72+(v/127)*0.28];};
// Spectral mode = chromatic rainbow. Each pitch class gets an evenly-spaced
// hue (30° steps) so the 12 PCs span the entire color wheel without gaps or
// duplicates. Replaces the previous wavelength-folding approach which
// clustered D#/E/F at violet and F#/G/G# at red with a discontinuous jump.
const SPEC_HUE=Array.from({length:12},(_,pc)=>pc*30);
const specCol=(m,v=100)=>{const h=SPEC_HUE[m%12];const s=75+(v/127)*15;const[r,g,b]=fromHsl(h,s,octL(m));return[r,g,b,0.65+(v/127)*0.35];};

function parseMidi(buf){
  const d=new Uint8Array(buf);let p=0;
  const u8=()=>d[p++];
  const u16=()=>{const v=(d[p]<<8)|d[p+1];p+=2;return v;};
  const u32=()=>{const v=(d[p]<<24)|(d[p+1]<<16)|(d[p+2]<<8)|d[p+3];p+=4;return v;};
  const vl=()=>{let v=0,b;do{b=u8();v=(v<<7)|(b&0x7f);}while(b&0x80);return v;};
  p+=4;u32();u16();
  const nT=u16(),div=u16();
  const temps=[{tick:0,uspb:500000}],raw=[],skipped=[];
  for(let t=0;t<nT;t++){
    // Scan forward to next MTrk header
    while(p+4<d.length&&!(d[p]===0x4d&&d[p+1]===0x54&&d[p+2]===0x72&&d[p+3]===0x6b))p++;
    if(p+8>d.length)break;
    p+=4;
    const tLen=u32(),tEnd=Math.min(p+tLen,d.length);
    const trackStart=p;
    try{
      let tick=0,st=0,held={};
      while(p<tEnd){
        tick+=vl();
        let s=d[p];if(s>=0x80){st=s;p++;}
        const tp=st&0xf0;
        if(tp===0x90){const pitch=u8(),vel=u8();if(vel>0)held[pitch]=[tick,vel];else if(held[pitch]){raw.push([pitch,held[pitch][0],held[pitch][1],tick]);delete held[pitch];}}
        else if(tp===0x80){const pitch=u8();u8();if(held[pitch]){raw.push([pitch,held[pitch][0],held[pitch][1],tick]);delete held[pitch];}}
        else if(st===0xff){const mt=u8(),ml=vl();if(mt===0x51&&ml===3){const uspb=(u8()<<16)|(u8()<<8)|u8();temps.push({tick,uspb});}else p+=ml;}
        else if(st===0xf0||st===0xf7){p+=vl();}
        else if(tp===0xb0||tp===0xe0||tp===0xa0){u8();u8();}
        else if(tp===0xc0||tp===0xd0){u8();}
      }
      // Flush any held notes at track end
      for(const pi in held)raw.push([parseInt(pi),held[pi][0],held[pi][1],tEnd]);
    }catch(err){
      skipped.push(t+1); // 1-based track number for the user
    }
    p=tEnd; // always advance past the track regardless
  }
  raw.sort((a,b)=>a[1]-b[1]);
  temps.sort((a,b)=>a.tick-b.tick);
  return{raw,div,temps,skipped};
}
function t2ms(ticks,div,temps){let ms=0,prev=0,uspb=500000;for(const{tick:tc,uspb:u}of temps){if(tc>=ticks)break;ms+=(tc-prev)*uspb/div/1000;prev=tc;uspb=u;}return ms+(ticks-prev)*uspb/div/1000;}

// Shared normalizer: takes a flat array of {m, startMs, durMs, v}, groups
// simultaneous notes (within CWIN ms) into chord events, and computes durQ.
// Both toChords (MIDI ticks) and noteArr2events (beat/BPM) resolve their
// format first, then delegate here.
function groupToEvents(flat,quarterMs){
  if(!flat.length)return[];
  flat.sort((a,b)=>a.startMs-b.startMs);
  const out=[];let i=0;
  while(i<flat.length){
    const bt=flat[i].startMs,g=[];
    while(i<flat.length&&flat[i].startMs-bt<=CWIN){g.push(flat[i]);i++;}
    const maxDur=Math.max(...g.map(n=>n.durMs));
    out.push({n:g.map(({m,v,durMs})=>({m,v,durMs})),startMs:bt,durQ:snapDurQ(maxDur/(quarterMs||500))});
  }
  return out;
}

function toChords(raw,div,temps){
  if(!raw.length)return[];
  const uspb=temps[temps.length-1]?.uspb||500000,quarterMs=uspb/1000;
  const flat=raw.map(([m,st,v,et])=>({m,v,startMs:t2ms(st,div,temps),durMs:Math.max(80,t2ms(et,div,temps)-t2ms(st,div,temps))}));
  return groupToEvents(flat,quarterMs);
}

// Paint-mode setting tables
const PAINT_DURS = [
  {ms:125, label:'1/16'},
  {ms:250, label:'1/8'},
  {ms:500, label:'1/4'},
  {ms:1000, label:'1/2'},
  {ms:2000, label:'1'},
];
const PAINT_VELS = [
  {v:55, label:'p'},
  {v:78, label:'mp'},
  {v:95, label:'mf'},
  {v:115, label:'f'},
];
const PAINT_SCALES = {
  off:  {label:'free',  root:0, scale:null},
  cmaj: {label:'C maj', root:0, scale:[0,2,4,5,7,9,11]},
  amin: {label:'A min', root:9, scale:[0,2,3,5,7,8,10]},
  gmaj: {label:'G maj', root:7, scale:[0,2,4,5,7,9,11]},
  emin: {label:'E min', root:4, scale:[0,2,3,5,7,8,10]},
  dmaj: {label:'D maj', root:2, scale:[0,2,4,5,7,9,11]},
  fmaj: {label:'F maj', root:5, scale:[0,2,4,5,7,9,11]},
  dmin: {label:'D min', root:2, scale:[0,2,3,5,7,8,10]},
};
const PAINT_SCALE_KEYS = ['off','cmaj','amin','gmaj','emin','dmaj','fmaj','dmin'];

function paintScalePCs(scaleKey){
  const s = PAINT_SCALES[scaleKey];
  if(!s || !s.scale) return null;
  return s.scale.map(o => (o + s.root) % 12);
}
function paintSnapMidi(midi, scaleKey){
  const pcs = paintScalePCs(scaleKey);
  if(!pcs) return midi;
  const oct = Math.floor(midi/12), pc = midi%12;
  let best=pcs[0], bestD=12;
  for(const sp of pcs){
    const d = Math.min(Math.abs(pc-sp), 12-Math.abs(pc-sp));
    if(d<bestD){bestD=d; best=sp;}
  }
  const cands = [oct*12+best, (oct-1)*12+best, (oct+1)*12+best];
  return cands.reduce((a,b)=>Math.abs(b-midi)<Math.abs(a-midi)?b:a);
}

function snapDurQ(q){const t=[0.25,0.5,0.75,1,1.5,2,3,4];let b=1,bd=Infinity;for(const x of t){const d=Math.abs(q-x);if(d<bd){bd=d;b=x;}}return b;}

// Decompress a .mxl (zipped MusicXML) ArrayBuffer to the inner XML text.
// Uses inline ZIP parsing + browser's built-in DecompressionStream — no library, ~50 LOC.
// Works on iOS Safari 16.4+, Chrome 80+, Firefox 113+.
async function mxlToXml(buf){
  const bytes=new Uint8Array(buf);
  const dv=new DataView(buf);
  // Find End-of-Central-Directory record (EOCD signature 0x06054b50), scanning from file end backwards
  let eocd=-1;
  for(let i=bytes.length-22;i>=0&&i>=bytes.length-65557;i--){
    if(dv.getUint32(i,true)===0x06054b50){eocd=i;break;}
  }
  if(eocd<0) throw new Error('Not a valid .mxl (no EOCD record)');
  const cdEntries=dv.getUint16(eocd+10,true);
  const cdOffset=dv.getUint32(eocd+16,true);
  // Walk the central directory
  const files=[];
  let p=cdOffset;
  for(let i=0;i<cdEntries;i++){
    if(dv.getUint32(p,true)!==0x02014b50) throw new Error('Corrupt .mxl central directory');
    const method=dv.getUint16(p+10,true);
    const compSize=dv.getUint32(p+20,true);
    const fnameLen=dv.getUint16(p+28,true);
    const extraLen=dv.getUint16(p+30,true);
    const commentLen=dv.getUint16(p+32,true);
    const lfh=dv.getUint32(p+42,true);
    const name=new TextDecoder().decode(bytes.slice(p+46,p+46+fnameLen));
    files.push({name,method,compSize,lfh});
    p+=46+fnameLen+extraLen+commentLen;
  }
  // Pick the main score file: prefer .musicxml or .xml not in META-INF.
  // If META-INF/container.xml exists we could parse it for the rootfile path, but the heuristic below works for all musescore.com / MuseScore Studio exports.
  const main=files.find(f=>!f.name.startsWith('META-INF')&&(f.name.endsWith('.musicxml')||f.name.endsWith('.xml')))
           ||files.find(f=>f.name.endsWith('.xml'));
  if(!main) throw new Error('No score file inside .mxl');
  // Local file header → actual data offset
  if(dv.getUint32(main.lfh,true)!==0x04034b50) throw new Error('Corrupt .mxl file header');
  const lfnLen=dv.getUint16(main.lfh+26,true);
  const lexLen=dv.getUint16(main.lfh+28,true);
  const dataAt=main.lfh+30+lfnLen+lexLen;
  const compressed=bytes.slice(dataAt,dataAt+main.compSize);
  let xmlBytes;
  if(main.method===0){
    // Stored, no compression
    xmlBytes=compressed;
  }else if(main.method===8){
    // Deflate (raw, no zlib header)
    if(typeof DecompressionStream==='undefined'){
      throw new Error('This browser is too old to read compressed .mxl. Update Safari/Chrome, or re-export as uncompressed .musicxml.');
    }
    const stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
    xmlBytes=new Uint8Array(await new Response(stream).arrayBuffer());
  }else{
    throw new Error('Unsupported .mxl compression method: '+main.method);
  }
  return new TextDecoder('utf-8').decode(xmlBytes);
}

// MusicXML parser — converts MuseScore/Finale/Dorico XML exports into Paintiano events.
// Reads pitches, durations, voices, chords, multi-staff piano directly — no OMR guessing.
// Accepts uncompressed .musicxml / .xml only (compressed .mxl needs unzip and is not supported here).
function parseMusicXml(xmlText){
  const doc=new DOMParser().parseFromString(xmlText,'application/xml');
  const err=doc.querySelector('parsererror');
  if(err) throw new Error('Invalid MusicXML: '+(err.textContent||'').replace(/\s+/g,' ').slice(0,80));
  if(!doc.querySelector('score-partwise, score-timewise')) throw new Error('Not a MusicXML score (no <score-partwise> root). If you exported .mxl, re-export as uncompressed .musicxml.');
  const stepSemi={C:0,D:2,E:4,F:5,G:7,A:9,B:11};
  const notes=[]; // [{startQ, durQ, midi, vel}]
  let lastNoteStartQ=0;
  for(const part of doc.querySelectorAll('score-partwise > part')){
    let divisions=4;
    let curTimeQ=0;
    for(const measure of part.querySelectorAll(':scope > measure')){
      for(const elem of measure.children){
        const tag=elem.tagName;
        if(tag==='attributes'){
          const div=elem.querySelector(':scope > divisions');
          if(div) divisions=parseInt(div.textContent)||divisions;
        }else if(tag==='note'){
          if(elem.querySelector(':scope > grace')) continue; // skip grace notes
          const isChord=elem.querySelector(':scope > chord')!==null;
          const isRest=elem.querySelector(':scope > rest')!==null;
          const durEl=elem.querySelector(':scope > duration');
          const duration=durEl?parseFloat(durEl.textContent):0;
          const durQ=duration/divisions;
          if(isRest){
            if(!isChord) curTimeQ+=durQ;
            continue;
          }
          const pitchEl=elem.querySelector(':scope > pitch');
          if(!pitchEl){
            if(!isChord) curTimeQ+=durQ;
            continue;
          }
          const step=pitchEl.querySelector(':scope > step')?.textContent||'C';
          const octave=parseInt(pitchEl.querySelector(':scope > octave')?.textContent||'4');
          const alter=parseFloat(pitchEl.querySelector(':scope > alter')?.textContent||'0');
          const midi=Math.round((octave+1)*12+(stepSemi[step]||0)+alter);
          // Dynamics → velocity
          let vel=88;
          const dyn=elem.querySelector(':scope > notations > dynamics');
          if(dyn){
            const tag=dyn.children[0]?.tagName;
            const dynMap={ppp:30,pp:42,p:55,mp:70,mf:85,f:100,ff:115,fff:127,sf:110,sfz:115,fp:80};
            if(tag&&dynMap[tag.toLowerCase()]) vel=dynMap[tag.toLowerCase()];
          }
          // For chord notes: same startQ as the previous note in this voice/part; curTimeQ wasn't advanced
          const noteStartQ=isChord?lastNoteStartQ:curTimeQ;
          if(midi>=0&&midi<128) notes.push({startQ:noteStartQ,durQ,midi,vel});
          if(!isChord){
            lastNoteStartQ=curTimeQ;
            curTimeQ+=durQ;
          }
        }else if(tag==='backup'){
          const dur=parseFloat(elem.querySelector(':scope > duration')?.textContent||'0');
          curTimeQ=Math.max(0,curTimeQ-dur/divisions);
        }else if(tag==='forward'){
          const dur=parseFloat(elem.querySelector(':scope > duration')?.textContent||'0');
          curTimeQ+=dur/divisions;
        }
      }
    }
  }
  if(!notes.length) throw new Error('No playable notes found in MusicXML.');
  // Sort by start time, then pitch (for stable chord rendering low→high)
  notes.sort((a,b)=>a.startQ-b.startQ||a.midi-b.midi);
  // Group simultaneous notes into chord events
  const events=[];
  const EPS=0.005;
  for(const n of notes){
    const last=events[events.length-1];
    if(last&&Math.abs(last.startQ-n.startQ)<EPS){
      last.notes.push({m:n.midi,v:n.vel,durMs:Math.round(n.durQ*500)});
      last.maxDurQ=Math.max(last.maxDurQ,n.durQ);
    }else{
      events.push({startQ:n.startQ,maxDurQ:n.durQ,notes:[{m:n.midi,v:n.vel,durMs:Math.round(n.durQ*500)}]});
    }
  }
  // Deduplicate identical pitches within each chord (multi-voice unisons)
  for(const ev of events){
    const seen=new Set();
    ev.notes=ev.notes.filter(n=>seen.has(n.m)?false:(seen.add(n.m),true));
  }
  // Build Paintiano events. Fixed 100 BPM means 600 ms per quarter; durations scale from durQ.
  const QUARTER_MS=600;
  return events.map((c,idx)=>{
    const dms=Math.max(120,Math.round(c.maxDurQ*QUARTER_MS));
    return{
      n:c.notes.map(n=>({m:n.m,v:n.v,durMs:dms})),
      startMs:Math.round(c.startQ*QUARTER_MS),
      idx,
      durQ:snapDurQ(c.maxDurQ)
    };
  });
}
function computeGrid(arg){
  const evs=Array.isArray(arg)?arg:new Array(arg).fill(null).map(()=>({durQ:1}));
  const totalQ=evs.reduce((s,e)=>s+(e.durQ!=null?e.durQ:1),0);
  const N=Math.max(2,Math.ceil(Math.sqrt(totalQ)));
  const rows=Math.max(1,Math.ceil(totalQ/N));
  // Uniform global scale: every event's durQ is multiplied by this so the totals fill exactly N*rows cells.
  // This way every block keeps the SAME unit width across the whole canvas (no per-row stretching) and the
  // last row reaches the right edge naturally. Long events that overrun a row wrap into the next row as
  // additional segments — visually continuing the same chord on the next line, no empty space at row ends.
  const scale=(N*rows)/totalQ;
  const BW=Math.max(4,Math.floor(480/N));
  const BH=Math.round(BW*PHI);
  const CW=N*BW;
  const CH=rows*BH;
  const cells=[];
  let curX=0,curY=0;
  for(let i=0;i<evs.length;i++){
    const dq=(evs[i].durQ!=null?evs[i].durQ:1)*scale;
    let remaining=dq*BW;
    const segments=[];
    while(remaining>0.5){
      const availableInRow=CW-curX;
      const segW=Math.min(remaining,availableInRow);
      segments.push({x:Math.round(curX),y:curY,w:Math.max(2,Math.round(segW)),h:BH});
      curX+=segW;
      remaining-=segW;
      if(curX>=CW-0.5){curX=0;curY+=BH;}
    }
    if(!segments.length){
      segments.push({x:Math.round(curX),y:curY,w:Math.max(2,Math.round(BW)),h:BH});
    }
    const f=segments[0];
    cells.push({idx:i,x:f.x,y:f.y,w:f.w,h:f.h,segments});
  }
  // Cleanup: if the very last event left a tiny stranded segment on a new bottom row,
  // absorb it so the canvas doesn't end with an isolated single cell.
  if(cells.length>0){
    const lastCell=cells[cells.length-1];
    const segs=lastCell.segments;
    if(segs.length>=2){
      // Last event has multiple segments — last one is a wrap-continuation. If it's tiny on its own row, drop it and extend the prev segment.
      const veryLast=segs[segs.length-1];
      const prev=segs[segs.length-2];
      if(veryLast.y>prev.y && veryLast.w<BW*1.5){
        segs.pop();
        prev.w=CW-prev.x;
      }
    }else if(segs.length===1 && cells.length>=2){
      // Last event is single segment alone on a new row. Try to slot it into the previous row by shrinking the prev cell's last segment.
      const veryLast=segs[0];
      const prevCell=cells[cells.length-2];
      const prevSegs=prevCell.segments;
      const prevLast=prevSegs[prevSegs.length-1];
      if(veryLast.y>prevLast.y && veryLast.x===0 && veryLast.w<BW*3){
        const shrinkBy=veryLast.w;
        if(prevLast.w>shrinkBy+BW){
          prevLast.w-=shrinkBy;
          veryLast.x=prevLast.x+prevLast.w;
          veryLast.y=prevLast.y;
          // Sync cell's x/y/w to first (and only) segment
          lastCell.x=veryLast.x;lastCell.y=veryLast.y;lastCell.w=veryLast.w;lastCell.h=veryLast.h;
        }else{
          // Not enough room — at least stretch the lonely segment so the bottom row isn't a single tiny cell
          veryLast.w=CW-veryLast.x;
          lastCell.w=veryLast.w;
        }
      }
    }
    // Always ensure the last segment reaches the right edge of its row (clean bottom-right corner)
    const finalSegs=cells[cells.length-1].segments;
    const finalLast=finalSegs[finalSegs.length-1];
    if(finalLast.x+finalLast.w<CW){finalLast.w=CW-finalLast.x;}
  }
  // CH may be slightly off if the last event rounded; recompute from cells
  const lastSeg=cells.length?cells[cells.length-1].segments[cells[cells.length-1].segments.length-1]:null;
  const finalCH=lastSeg?lastSeg.y+BH:CH;
  return{N,BW,BH,CW,CH:finalCH,cells,rows:Math.round(finalCH/BH),totalQ};
}
// Block renderers — three artist-styled mark-making languages plus the
// implicit mosaic default (no selection). drawBlock dispatches per-cell.
//   picasso:   angular cubist shards with thin black contour outlines
//   rembrandt: chiaroscuro impasto — shadow + bristles + ridge highlight + sparkle
//   monet:     soft circular dabs with luminosity-jittered hue field
//   mosaic:    the implicit default — sharp rectangles + thin halo, used when
//              no artist is explicitly selected. Not exposed in the toggle.

// Seeded RNG helper — same seed → same marks → no flicker between repaints.
function _seedRnd(bx,by,BW,BH){
  let seed=((bx*73)^(by*113)^(BW*271)^(BH*947))>>>0;
  return ()=>{seed=(seed*1664525+1013904223)>>>0;return seed/0x100000000;};
}

// Sharp φ-rectangle look — implicit default when no artist style selected.
function drawBlockMosaic(ctx,bx,by,notes,gc,BW,BH){const sorted=[...notes].sort((a,b)=>b.m-a.m),n=sorted.length,bh=BH/n;sorted.forEach((note,i)=>{const[r,g,b,a]=gc(note.m,note.v),y=by+i*bh;ctx.fillStyle=`rgba(${r},${g},${b},${(a*.18).toFixed(3)})`;ctx.fillRect(bx-2,y-2,BW+4,bh+4);ctx.fillStyle=`rgba(${r},${g},${b},${a.toFixed(3)})`;ctx.fillRect(bx+.5,y+.5,BW-1,bh-1);});if(n>1){ctx.fillStyle='rgba(4,4,10,0.7)';for(let i=1;i<n;i++)ctx.fillRect(bx+.5,by+i*bh-.5,BW-1,1);}}

function drawRembrandt(ctx,bx,by,notes,gc,BW,BH){
  // Chiaroscuro impasto: each chord scatters 3–4 brushstrokes per voice;
  // each stroke is built up from FOUR layers to fake the depth of real pigment:
  //   1) shadow — a darker, slightly-offset polygon beneath the stroke (depth)
  //   2) bristles — 4–6 parallel marks at slightly different tones (loaded brush)
  //   3) highlight — a thin lighter shape along the upper edge (paint ridge catching light)
  //   4) specular — an occasional near-white speck (wet-paint sparkle)
  // Edges use 12-vertex polygons with ±18% radius jitter so they read as
  // hand-painted, not vector-perfect. Per-chord stroke direction gives the
  // canvas gestural rhythm — strokes within a chord cluster around the same
  // angle, different chords go in different directions. Tone shifts are pure
  // luminosity so the chord's hue (and the harmony/spectral mode) reads clearly.
  const sorted=[...notes].sort((a,b)=>b.m-a.m),n=sorted.length,bh=BH/n;
  const rnd=_seedRnd(bx,by,BW,BH);
  // Hand-painted polygon — perturbed radii so the outline isn't perfectly smooth.
  const rough=(ax,ay,rx,ry)=>{
    const segs=12;
    ctx.beginPath();
    for(let i=0;i<segs;i++){
      const a=(i/segs)*Math.PI*2;
      const j=0.82+rnd()*0.36;
      const x=ax+Math.cos(a)*rx*j;
      const y=ay+Math.sin(a)*ry*j;
      if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
    }
    ctx.closePath();ctx.fill();
  };
  sorted.forEach((note,vi)=>{
    const[r,g,b,a]=gc(note.m,note.v);
    const yOff=by+vi*bh;
    // Voice-coherent stroke direction
    const chordAngle=rnd()*Math.PI*2;
    const count=3+Math.floor(rnd()*2); // 3–4 strokes per voice
    for(let k=0;k<count;k++){
      const cx=bx+rnd()*BW;
      const cy=yOff+rnd()*bh;
      const angle=chordAngle+(rnd()-0.5)*Math.PI/3; // chord direction ±30°
      const length=BW*(0.50+rnd()*0.45);
      const width=bh*(0.35+rnd()*0.30);
      ctx.save();
      ctx.translate(cx,cy);
      ctx.rotate(angle);
      // 1) Shadow — offset 1.5px down-right, darker colour
      const sR=Math.round(r*0.40), sG=Math.round(g*0.40), sB=Math.round(b*0.40);
      ctx.fillStyle=`rgba(${sR},${sG},${sB},${(a*0.55).toFixed(3)})`;
      rough(1.5,1.5,length*1.05,width*0.55);
      // 2) Body — 4–6 parallel bristle marks with alternating luminosity shifts
      // (uniform across R/G/B so hue is preserved — mode signal stays visible)
      const bristles=4+Math.floor(rnd()*3);
      for(let bi=0;bi<bristles;bi++){
        const t=(bi+0.5)/bristles;
        const yB=(t-0.5)*width;
        const tone=(bi%2===0?1:-1)*(10+rnd()*25);
        const br=Math.max(0,Math.min(255,Math.round(r+tone)));
        const bg=Math.max(0,Math.min(255,Math.round(g+tone)));
        const bb=Math.max(0,Math.min(255,Math.round(b+tone)));
        const op=a*(0.70+rnd()*0.30);
        ctx.fillStyle=`rgba(${br},${bg},${bb},${op.toFixed(3)})`;
        rough(0,yB,length*(0.85+rnd()*0.30),width/bristles*1.4);
      }
      // 3) Highlight — lighter ridge along the top edge of the stroke
      const hR=Math.min(255,Math.round(r+65)), hG=Math.min(255,Math.round(g+65)), hB=Math.min(255,Math.round(b+65));
      ctx.fillStyle=`rgba(${hR},${hG},${hB},${(a*0.45).toFixed(3)})`;
      rough(-length*0.05,-width*0.32,length*0.55,width*0.11);
      // 4) Specular sparkle — small near-white speck on wet paint, ~38% of strokes
      if(rnd()>0.62){
        ctx.fillStyle=`rgba(255,250,240,${(a*0.40).toFixed(3)})`;
        rough(-length*0.15+(rnd()-0.5)*length*0.3,-width*0.25,length*0.08,width*0.04);
      }
      ctx.restore();
    }
  });
}

function drawPicasso(ctx,bx,by,notes,gc,BW,BH){
  // Analytical cubism with three subdivision strategies picked at random per
  // cell, so adjacent cells look meaningfully different — not every cell is
  // the same pinwheel fan. Strategies (weights):
  //   • BISECT (35%)     — one cut: horizontal, vertical, or diagonal → 2 planes
  //   • CORNER FAN (30%) — pivot at a corner, 2–3 planes radiating across
  //   • CENTRE FAN (35%) — pivot inside, 4–6 planes (the prior look, slimmed)
  // Adjacent planes alternate brighter/darker for the broken-light effect.
  // Bold dark contour lines trace every plane edge — Picasso's architecture.
  // Tone shifts are uniform across R/G/B so chord hue (and the mode toggle)
  // stays legible through the fragmentation.
  const sorted=[...notes].sort((a,b)=>b.m-a.m),n=sorted.length,bh=BH/n;
  const rnd=_seedRnd(bx,by,BW,BH);
  sorted.forEach((note,vi)=>{
    const[r,g,b,a]=gc(note.m,note.v);
    const yOff=by+vi*bh;
    const x1=bx,y1=yOff,x2=bx+BW,y2=yOff+bh;
    const planes=[];
    const variant=rnd();
    if(variant<0.35){
      // BISECT — single cut through the cell, 2 planes
      const cutType=rnd();
      if(cutType<0.33){
        const cy=y1+bh*(0.30+rnd()*0.40);
        planes.push([{x:x1,y:y1},{x:x2,y:y1},{x:x2,y:cy},{x:x1,y:cy}]);
        planes.push([{x:x1,y:cy},{x:x2,y:cy},{x:x2,y:y2},{x:x1,y:y2}]);
      }else if(cutType<0.66){
        const cx=x1+BW*(0.30+rnd()*0.40);
        planes.push([{x:x1,y:y1},{x:cx,y:y1},{x:cx,y:y2},{x:x1,y:y2}]);
        planes.push([{x:cx,y:y1},{x:x2,y:y1},{x:x2,y:y2},{x:cx,y:y2}]);
      }else{
        // Diagonal cut: from a point on the left edge to a point on the right
        const lY=y1+bh*(0.20+rnd()*0.60);
        const rY=y1+bh*(0.20+rnd()*0.60);
        planes.push([{x:x1,y:y1},{x:x2,y:y1},{x:x2,y:rY},{x:x1,y:lY}]);
        planes.push([{x:x1,y:lY},{x:x2,y:rY},{x:x2,y:y2},{x:x1,y:y2}]);
      }
    }else if(variant<0.65){
      // CORNER FAN — pivot at one corner, fan to the opposite three corners
      const corners=[{x:x1,y:y1},{x:x2,y:y1},{x:x2,y:y2},{x:x1,y:y2}];
      const cornerIdx=Math.floor(rnd()*4);
      const pivot=corners[cornerIdx];
      const walk=[];
      for(let i=1;i<=3;i++)walk.push(corners[(cornerIdx+i)%4]);
      // Optionally insert 1 mid-edge point between two corners of the walk
      if(rnd()>0.35){
        const insertAt=1+Math.floor(rnd()*2);
        const a1=walk[insertAt-1], a2=walk[insertAt];
        let mid;
        if(a1.x===a2.x)mid={x:a1.x,y:a1.y+(a2.y-a1.y)*(0.30+rnd()*0.40)};
        else mid={x:a1.x+(a2.x-a1.x)*(0.30+rnd()*0.40),y:a1.y};
        walk.splice(insertAt,0,mid);
      }
      for(let i=0;i<walk.length-1;i++)planes.push([pivot,walk[i],walk[i+1]]);
    }else{
      // CENTRE FAN — pivot inside cell, 4–6 planes radiating to boundary
      const px=x1+BW*(0.30+rnd()*0.40);
      const py=y1+bh*(0.30+rnd()*0.40);
      const pivot={x:px,y:py};
      const boundary=[{x:x1,y:y1}];
      if(rnd()>0.55)boundary.push({x:x1+BW*(0.25+rnd()*0.50),y:y1});
      boundary.push({x:x2,y:y1});
      if(rnd()>0.55)boundary.push({x:x2,y:y1+bh*(0.25+rnd()*0.50)});
      boundary.push({x:x2,y:y2});
      if(rnd()>0.55)boundary.push({x:x1+BW*(0.25+rnd()*0.50),y:y2});
      boundary.push({x:x1,y:y2});
      if(rnd()>0.55)boundary.push({x:x1,y:y1+bh*(0.25+rnd()*0.50)});
      for(let i=0;i<boundary.length;i++){
        const p1=boundary[i], p2=boundary[(i+1)%boundary.length];
        planes.push([p1,p2,pivot]);
      }
    }
    // Fill planes with alternating tone shifts
    for(let i=0;i<planes.length;i++){
      const tone=(i%2===0?1:-1)*(35+rnd()*45);
      const rJ=Math.max(0,Math.min(255,Math.round(r+tone)));
      const gJ=Math.max(0,Math.min(255,Math.round(g+tone)));
      const bJ=Math.max(0,Math.min(255,Math.round(b+tone)));
      ctx.fillStyle=`rgba(${rJ},${gJ},${bJ},${a.toFixed(3)})`;
      const poly=planes[i];
      ctx.beginPath();
      ctx.moveTo(poly[0].x,poly[0].y);
      for(let j=1;j<poly.length;j++)ctx.lineTo(poly[j].x,poly[j].y);
      ctx.closePath();
      ctx.fill();
    }
    // Bold architectural contour outlines
    ctx.strokeStyle='rgba(12,8,4,0.78)';
    ctx.lineWidth=1.3;
    ctx.lineCap='round';
    ctx.lineJoin='round';
    for(const poly of planes){
      ctx.beginPath();
      ctx.moveTo(poly[0].x,poly[0].y);
      for(let j=1;j<poly.length;j++)ctx.lineTo(poly[j].x,poly[j].y);
      ctx.closePath();
      ctx.stroke();
    }
  });
}

function drawMonet(ctx,bx,by,notes,gc,BW,BH){
  // Impressionist dabs: 8–12 soft circular marks per voice with luminosity
  // jitter (light/shadow across same hue) and radial-gradient feathered
  // edges. Adjacent dabs overlap and blend optically — the cell becomes a
  // colour field, no hard borders. Light, airy, Giverny-pond palette feel.
  // Jitter is applied uniformly across R/G/B so the chord's hue identity is
  // preserved — without this, the asymmetric jitter would wash out the
  // harmony-vs-spectral colour difference.
  const sorted=[...notes].sort((a,b)=>b.m-a.m),n=sorted.length,bh=BH/n;
  const rnd=_seedRnd(bx,by,BW,BH);
  sorted.forEach((note,vi)=>{
    const[r,g,b,a]=gc(note.m,note.v);
    const yOff=by+vi*bh;
    const count=8+Math.floor(rnd()*5); // 8–12 dabs
    for(let k=0;k<count;k++){
      const cx=bx+rnd()*BW;
      const cy=yOff+rnd()*bh;
      const radius=Math.min(BW,bh)*(0.20+rnd()*0.25);
      // Pure luminosity shift — same hue, varying brightness like dappled light
      const tone=(rnd()-0.5)*55;
      const rJ=Math.max(0,Math.min(255,Math.round(r+tone)));
      const gJ=Math.max(0,Math.min(255,Math.round(g+tone)));
      const bJ=Math.max(0,Math.min(255,Math.round(b+tone)));
      // Soft feathered dab via radial gradient
      const grad=ctx.createRadialGradient(cx,cy,0,cx,cy,radius);
      grad.addColorStop(0,`rgba(${rJ},${gJ},${bJ},${(a*0.78).toFixed(3)})`);
      grad.addColorStop(0.55,`rgba(${rJ},${gJ},${bJ},${(a*0.40).toFixed(3)})`);
      grad.addColorStop(1,`rgba(${rJ},${gJ},${bJ},0)`);
      ctx.fillStyle=grad;
      ctx.fillRect(cx-radius,cy-radius,radius*2,radius*2);
    }
  });
}

function drawBlock(ctx,bx,by,notes,gc,BW,BH,style){
  if(style==='picasso')return drawPicasso(ctx,bx,by,notes,gc,BW,BH);
  if(style==='rembrandt')return drawRembrandt(ctx,bx,by,notes,gc,BW,BH);
  if(style==='monet')return drawMonet(ctx,bx,by,notes,gc,BW,BH);
  return drawBlockMosaic(ctx,bx,by,notes,gc,BW,BH); // implicit default
}

// Convert a downsampled-image pixel array into musical events using a given hue→pitch table
// (COF for harmony mode, SPEC_HUE for spectral mode). Pure: same input + same table → same output.
function pixelsToImageEvents(px,nc,nr,table){
  // Time dilation: distribute the canvas of cells across exactly IMG_TARGET_MS.
  // noteDur slightly overshoots msPerBlock for legato between cells.
  const CHORD_SIZE=6;
  const COL_STEP=4;                              // merge 4 adjacent columns per time-event
  const _nrBands=Math.floor(nr/CHORD_SIZE);
  const effCols=Math.ceil(nc/COL_STEP);          // 192/4 = 48 events per band → 960 total
  const msPerBlock=IMG_TARGET_MS/(_nrBands*effCols); // 120000/960 ≈ 125ms per chord
  const noteDur=Math.round(msPerBlock*5);        // ~625ms sustain → ~5 chords overlap
  // ─── Color statistics pass ──
  // Find the dominant background hue and the average chroma so we can suppress
  // monochrome fields (e.g. Chagall's cobalt sky, Rothko-like color blocks) and
  // let figurative / colourful elements actually surface musically rather than
  // being buried in a single-note drone from 60-70% of the canvas.
  const hueHist=new Float32Array(36); // 10° bins, weighted by saturation
  let chSum=0,chN=0;
  for(const p of px){
    const[hh,ss,ll]=toHsl(p.r,p.g,p.b);
    if(ll<6||ll>94||ss<10)continue;
    hueHist[Math.floor(hh/10)%36]+=ss;
    chSum+=ss*Math.min(ll,100-ll)/50; chN++;
  }
  let bgBin=0,bgMax=0;
  for(let i=0;i<36;i++)if(hueHist[i]>bgMax){bgMax=hueHist[i];bgBin=i;}
  const bgHue=bgBin*10+5;
  const avgChroma=chN?chSum/chN:25;
  // Saliency floor scales with the image's overall chroma so a vivid painting
  // doesn't get over-suppressed, but a monochrome one does.
  const salFloor=Math.max(28,avgChroma*0.85);
  // Convert a pixel to a note, with optional "soft" mode that bypasses the
  // saliency filter (used as a safety fallback so each chord always has at
  // least one voice instead of dropping out to silence).
  function pxToNote(idx, soft){
    const{r,g,b}=px[idx],[h,s,l]=toHsl(r,g,b);
    // ── GRAYSCALE PATH ──
    // Achromatic pixels (white / grey / black) carry no hue information but
    // they DO carry value information. Map them to pitch class C with octave
    // driven by lightness: black ≈ C2 (deep bass), mid-grey ≈ C5 (middle),
    // white ≈ C7 (high treble). This forms a structural backbone under the
    // colour melody and keeps monochrome regions audible instead of silent.
    if (s < 10) {
      const oct = Math.max(2, Math.min(7, Math.round(2 + (l/100) * 5)));
      const midi = (oct + 1) * 12; // pitch class 0 = C
      // Contrast-driven velocity: pure black and pure white speak louder than
      // muddy mid-grey, so the visual extremes are also the sonic extremes.
      const contrast = Math.abs(l - 50) * 2; // 0 (mid-grey) … 100 (black/white)
      const v = Math.round(45 + (contrast/100) * 50); // 45 … 95
      return { m: midi, v, durMs: noteDur };
    }
    // ── CHROMATIC PATH ──
    // Saturated pixels at near-black or near-white extremes contain little
    // visible colour information, so we drop them; the grayscale branch above
    // already covers achromatic value extremes.
    if (l < 6 || l > 94) return null;
    const dh=Math.min(Math.abs(h-bgHue),360-Math.abs(h-bgHue));
    const chroma=s*Math.min(l,100-l)/50; // 0..100
    const isBackgroundHue = dh < 30;
    const isNearBackground = dh < 50;
    if (!soft) {
      // Tiered threshold: background hue must be more vivid to pass; off-
      // background hues get a low bar so colourful accents play prominently.
      const requiredChroma = isBackgroundHue
        ? salFloor * 1.15
        : isNearBackground
          ? salFloor * 0.65
          : salFloor * 0.40;
      if (chroma < requiredChroma) return null;
    }
    // Pitch: hue → COF/SPEC_HUE table
    let pc=0,minD=Infinity;
    table.forEach((th,ti)=>{const d=Math.min(Math.abs(h-th),360-Math.abs(h-th));if(d<minD){minD=d;pc=ti;}});
    // Octave: lightness → register, compressed to 3..6
    const oct=Math.max(3,Math.min(6,3+Math.round((l-20)/72*3)));
    const midi=(oct+1)*12+pc;
    // Velocity: chroma drives dynamics. Background-hue cells are attenuated
    // so the non-background palette stays in foreground.
    let v = Math.round(38 + (chroma/100) * 68);
    if (isBackgroundHue) v = Math.round(v * 0.6);
    else if (isNearBackground) v = Math.round(v * 0.82);
    return{m:midi,v,durMs:noteDur};
  }
  // Pick the most vivid of three row-pixels at (band, col) — used when the
  // strict filter would have left this chord empty. Guarantees audible music.
  function pickMostVivid(band, col){
    let best=null, bestCh=-1;
    for(let j=0;j<CHORD_SIZE;j++){
      const row=band*CHORD_SIZE+j; if(row>=nr) break;
      const idx=row*nc+col;
      const{r,g,b}=px[idx],[ , s, l]=toHsl(r,g,b);
      const ch = s * Math.min(l, 100-l) / 50;
      if (ch > bestCh) { bestCh = ch; best = idx; }
    }
    return best != null ? pxToNote(best, true) : null;
  }
  const evts=[];
  const nrBands=_nrBands;
  let evIdx=0;
  for(let band=0;band<nrBands;band++){
    for(let cg=0;cg<effCols;cg++){
      // Collect notes from all COL_STEP columns in this group for a richer chord
      const notes=[];
      const seenM=new Set();
      for(let sk=0;sk<COL_STEP;sk++){
        const col=cg*COL_STEP+sk; if(col>=nc) break;
        for(let j=0;j<CHORD_SIZE;j++){
          const row=band*CHORD_SIZE+j; if(row>=nr) break;
          const n=pxToNote(row*nc+col);
          if(n&&!seenM.has(n.m)){seenM.add(n.m);notes.push(n);}
        }
      }
      // Fallback: grab the most vivid pixel anywhere in the column group
      if(notes.length===0){
        for(let sk=0;sk<COL_STEP&&notes.length===0;sk++){
          const col=cg*COL_STEP+sk; if(col>=nc) break;
          const fallback=pickMostVivid(band,col);
          if(fallback&&!seenM.has(fallback.m)){seenM.add(fallback.m);notes.push(fallback);}
        }
      }
      evts.push({n:notes,startMs:evIdx*msPerBlock,idx:evIdx,cg,colStep:COL_STEP});
      evIdx++;
    }
  }
  // ─── Music theory pass ──
  // 1) Krumhansl-Schmuckler key detection
  const pcCounts=new Array(12).fill(0);
  evts.forEach(ev=>ev.n.forEach(n=>pcCounts[n.m%12]++));
  const MAJOR_P=[6.35,2.23,3.48,2.33,4.38,4.09,2.52,5.19,2.39,3.66,2.29,2.88];
  const MINOR_P=[6.33,2.68,3.52,5.38,2.60,3.53,2.54,4.75,3.98,2.69,3.34,3.17];
  let bestKey=0,bestModeIsMajor=true,bestCorr=-Infinity;
  for(let key=0;key<12;key++){
    for(const isMaj of[true,false]){
      const prof=isMaj?MAJOR_P:MINOR_P;
      let corr=0;
      for(let i=0;i<12;i++)corr+=pcCounts[(i+key)%12]*prof[i];
      if(corr>bestCorr){bestCorr=corr;bestKey=key;bestModeIsMajor=isMaj;}
    }
  }
  const MAJ_OFFSETS=[0,2,4,5,7,9,11];
  const MIN_OFFSETS=[0,2,3,5,7,8,10];
  const scalePCs=(bestModeIsMajor?MAJ_OFFSETS:MIN_OFFSETS).map(o=>(o+bestKey)%12);
  function snapToScale(midi){
    const oct=Math.floor(midi/12);
    let bestPC=scalePCs[0],bestD=99;
    for(const s of scalePCs){const d=Math.min(Math.abs(midi%12-s),12-Math.abs(midi%12-s));if(d<bestD){bestD=d;bestPC=s;}}
    const cands=[oct*12+bestPC,(oct-1)*12+bestPC,(oct+1)*12+bestPC];
    return cands.reduce((a,b)=>Math.abs(b-midi)<Math.abs(a-midi)?b:a);
  }
  function tightenChord(notes){
    if(notes.length<=1)return notes;
    const sorted=[...notes].sort((a,b)=>a.m-b.m);
    const anchor=sorted[Math.floor(sorted.length/2)].m;
    return notes.map(n=>{let m=n.m;while(m>anchor+17)m-=12;while(m<anchor-17)m+=12;return{...n,m};});
  }
  function removeM2(notes){
    if(notes.length<=1)return notes;
    const byVel=[...notes].sort((a,b)=>(b.v||0)-(a.v||0));
    const kept=[];
    for(const n of byVel){if(kept.some(k=>Math.abs(k.m-n.m)===1))continue;kept.push(n);}
    return kept;
  }
  // Harmonize: when a cell's 3 row-pixels all snap to the same MIDI (e.g. a
  // uniform-color cell), the dedup pass collapses it to a single tone. Build
  // a proper triad on that note's scale degree (root + third + fifth from the
  // detected key) so each cell always sounds with full polyphony. Only adds
  // notes that aren't already present — pre-existing chord tones are kept.
  function harmonizeToTriad(notes){
    if(notes.length===0||notes.length>=3)return notes;
    // Use highest-velocity note as the root for harmonization
    const sorted=[...notes].sort((a,b)=>(b.v||64)-(a.v||64));
    const root=sorted[0];
    const rootPc=((root.m%12)+12)%12;
    const scaleIdx=scalePCs.indexOf(rootPc);
    if(scaleIdx<0)return notes;
    // Triad: scale degrees 1, 3, 5 (i.e. indices 0, 2, 4 in the 7-note scale)
    const thirdPc=scalePCs[(scaleIdx+2)%7];
    const fifthPc=scalePCs[(scaleIdx+4)%7];
    // Place third and fifth in the closest octave above the root
    const baseOct=Math.floor(root.m/12);
    let thirdM=baseOct*12+thirdPc; if(thirdM<=root.m)thirdM+=12;
    let fifthM=baseOct*12+fifthPc; if(fifthM<=thirdM)fifthM+=12;
    // Cap at sensible piano range
    if(thirdM>96||fifthM>96)return notes;
    const existing=new Set(notes.map(n=>n.m));
    const result=[...notes];
    if(!existing.has(thirdM))result.push({...root,m:thirdM,v:Math.round((root.v||64)*0.72)});
    if(!existing.has(fifthM))result.push({...root,m:fifthM,v:Math.round((root.v||64)*0.68)});
    return result;
  }
  for(const ev of evts){
    ev.n=ev.n.map(n=>({...n,m:snapToScale(n.m)}));
    ev.n=tightenChord(ev.n);
    ev.n=removeM2(ev.n);
    const seen=new Set();
    ev.n=ev.n.filter(n=>seen.has(n.m)?false:(seen.add(n.m),true));
    ev.n=harmonizeToTriad(ev.n);
  }
  // Merge identical consecutive chords for legato, capped at whole note
  const chordKey=ns=>ns.length?ns.map(n=>n.m).sort((a,b)=>a-b).join(','):'';
  const MAX_RUN=4;
  let mi=0;
  while(mi<evts.length){
    const key=chordKey(evts[mi].n);
    if(!key){mi++;continue;}
    let mj=mi+1;
    while(mj<evts.length&&chordKey(evts[mj].n)===key)mj++;
    let k=mi;
    while(k<mj){
      const groupLen=Math.min(MAX_RUN,mj-k);
      if(groupLen>1){
        evts[k]._runLen=groupLen;
        for(let x=k+1;x<k+groupLen;x++)evts[x]._playable=false;
      }
      k+=groupLen;
    }
    mi=mj;
  }
  return evts;
}

const BKS=new Set([1,3,6,8,10]);
const{w:WKEYS,b:BKEYS}=(()=>{const w=[],b=[];let wi=0;for(let m=21;m<=108;m++){const pc=m%12;if(!BKS.has(pc))w.push({midi:m,wi:wi++});else b.push({midi:m,lw:wi-1});}return{w,b};})();
// Pixel x-position of a MIDI key on the keyboard strip. WKW=26 px per white key.
// Black keys sit between whites at offset +0.65 — same constant the JSX uses below.
const midiToKeyX = (midi) => {
  const w = WKEYS.find(k => k.midi === midi);
  if (w) return w.wi * 26;
  const b = BKEYS.find(k => k.midi === midi);
  if (b) return (b.lw + 0.65) * 26;
  return null;
};
// Scientific pitch notation for a MIDI number. Middle C (MIDI 60) → "C4".
// Uses sharps for the black keys (the most common piano notation).
const NOTE_PCS = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
const noteName = (m) => NOTE_PCS[((m % 12) + 12) % 12] + (Math.floor(m / 12) - 1);
// Pre-built lookup tables: O(1) for both directions across the full MIDI range.
const _midiToName = Array.from({length:128},(_,i)=>noteName(i));
const _nameToMidi = Object.fromEntries(_midiToName.map((n,i)=>[n,i]));
const LEGEND=[{n:'C',pc:0},{n:'G',pc:7},{n:'D',pc:2},{n:'A',pc:9},{n:'E',pc:4},{n:'B',pc:11},{n:'F#',pc:6},{n:'D♭',pc:1},{n:'A♭',pc:8},{n:'E♭',pc:3},{n:'B♭',pc:10},{n:'F',pc:5}];

// Chord recognition: given a set of MIDI numbers, return a chord name like "C maj" or null.
// Checks all 12 rotations (inversions) of the pitch-class set against common interval patterns.
function recognizeChord(midis){
  if(midis.length<2)return null;
  const pcs=[...new Set(midis.map(m=>m%12))].sort((a,b)=>a-b);
  if(pcs.length<2)return null;
  // Interval patterns from root: [intervals from root] → suffix
  const PATTERNS=[
    [[4,7],'maj'],[[ 3,7],'min'],[[4,7,11],'maj7'],[[4,7,10],'7'],
    [[3,7,10],'m7'],[[3,6],'dim'],[[4,8],'aug'],[[2,7],'sus2'],
    [[5,7],'sus4'],[[3,6,10],'m7♭5'],[[4,7,9],'6'],[[3,7,9],'m6'],
  ];
  for(let i=0;i<pcs.length;i++){
    const root=pcs[i];
    const intervals=pcs.map(p=>((p-root)+12)%12).filter(x=>x>0).sort((a,b)=>a-b);
    for(const[pat,suffix]of PATTERNS){
      if(pat.length===intervals.length&&pat.every((v,j)=>v===intervals[j])){
        return NOTE_PCS[root]+' '+suffix;
      }
    }
  }
  return null;
}

